<?php
require __DIR__.'/includes/bootstrap.php'; require_login(); require_member($pdo);
$month=$_GET['month']??budget_cycle_key();[,,$month]=budget_cycle_bounds($month);
$summary=family_budget_cycle_summary($pdo,$month);$buckets=budget_cycle_expense_buckets($pdo,$month);$saved=budget_cycle_savings($pdo,$month);$spend=budget_cycle_category_spend($pdo,$month);arsort($spend);
$totalExpense=max(0.0,(float)$summary['expense']);$net=(float)$summary['income']-$totalExpense;$rate=$summary['income']>0?round(($summary['income']-$totalExpense)/$summary['income']*100):0;
$prev=date('Y-m',strtotime($month.'-01 -1 month'));$prevSummary=family_budget_cycle_summary($pdo,$prev);$expenseDelta=$prevSummary['expense']>0?round((($summary['expense']-$prevSummary['expense'])/$prevSummary['expense'])*100):null;
$palette=['var(--blue)','#2f8f6b','#d46d5e','#7567d8','#b76e00','#2a8392','#9b59b6','#61758a','#cf5b8b','#5872d8'];$segments=[];$cursor=0.0;$i=0;
foreach($spend as $cat=>$amount){$pct=$totalExpense>0?($amount/$totalExpense*100):0;$segments[]=$palette[$i%count($palette)].' '.$cursor.'% '.($cursor+$pct).'%';$cursor+=$pct;$i++;}
$donut=$segments?'conic-gradient('.implode(',',$segments).')':'#e8edf4';
$pageTitle='Statistici';$active='money';require __DIR__.'/includes/layout_top.php';
?>
<form class="month-switch" method="get"><label>Ciclu început în<input type="month" name="month" value="<?=e($month)?>"></label><button class="btn soft">Vezi intervalul</button></form>
<section class="month-report"><div class="report-head"><div><h2><?=e(budget_cycle_label($month))?></h2><p>Interval salarial: 14 → 13. Salariul din 14, avansul și bonurile din 30 și cardul alimentat în 1 sunt în același ciclu.</p></div><span class="rate-chip <?=$rate>=0?'good':'bad'?>"><?=$rate?>% rămas</span></div><div class="report-grid"><div><span>Încasări</span><strong><?=money_ro($summary['income'])?></strong></div><div><span>Cheltuieli</span><strong><?=money_ro($summary['expense'])?></strong></div><div><span>Economii</span><strong><?=money_ro($saved)?></strong></div><div><span>Rămas</span><strong><?=money_ro($net)?></strong></div></div><?php if($expenseDelta!==null):?><p class="report-compare">Cheltuieli față de luna trecută: <b><?=$expenseDelta>0?'+':''?><?=$expenseDelta?>%</b></p><?php endif;?></section>
<section class="finance-split"><article><span class="split-icon fixed"><?=icon('receipt')?></span><div><span>Costuri fixe</span><strong><?=money_ro($buckets['fixed'])?></strong><small>rate, abonamente, facturi</small></div></article><article><span class="split-icon variable"><?=icon('sparkles')?></span><div><span>Costuri variabile</span><strong><?=money_ro($buckets['variable'])?></strong><small>cumpărături, mâncare, shopping</small></div></article><article><span class="split-icon saving"><?=icon('piggy')?></span><div><span>Economii</span><strong><?=money_ro($saved)?></strong><small>bani puși deoparte</small></div></article></section>
<section class="chart-card category-report"><div class="section-head compact"><div><h2>Cheltuieli pe categorii</h2><p>Apasă o categorie pentru tranzacțiile care formează suma.</p></div></div><?php if(!$spend):?><div class="empty">Nu sunt cheltuieli în intervalul selectat.</div><?php else:?><div class="category-donut-wrap"><div class="category-donut" style="background:<?=$donut?>"><div><strong><?=money_ro($totalExpense)?></strong><span>Total</span></div></div><div class="category-legend"><?php $i=0;foreach($spend as $cat=>$amount):$pct=$totalExpense>0?round($amount/$totalExpense*100):0;?><a href="/transactions.php?month=<?=e($month)?>&type=expense&category=<?=urlencode($cat)?>"><i style="background:<?=$palette[$i%count($palette)]?>"></i><span><b><?=e($cat)?></b><small><?=money_ro($amount)?> · <?=$pct?>%</small></span><em><?=icon('chevron')?></em></a><?php $i++;endforeach;?></div></div><?php endif;?></section>
